questions.solution:
function memoizedFib(n) {
  let calls = 0
  function memoize(fn) {
    const cache = new Map()
    return function (x) {
      if (cache.has(x)) return cache.get(x)
      const result = fn(x)
      cache.set(x, result)
      return result
    }
  }
  const fib = memoize((x) => {
    calls++
    return x < 2 ? x : fib(x - 1) + fib(x - 2)
  })
  const value = fib(n)
  return { value, calls }
}

