solution.js:
const form = document.getElementById("signup");
const success = document.getElementById("success");

function validate(values) {
  const errors = {};
  if (values.name.trim().length < 2) errors.name = "Name must be at least 2 characters";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) errors.email = "Enter a valid email";
  if (values.password.length < 8 || !/\d/.test(values.password)) errors.password = "Min 8 characters and a number";
  if (values.confirm !== values.password || values.confirm === "") errors.confirm = "Passwords do not match";
  return errors;
}

form.addEventListener("submit", function (e) {
  e.preventDefault();
  const ids = ["name", "email", "password", "confirm"];
  const values = {};
  ids.forEach(function (id) { values[id] = document.getElementById(id).value; });
  const errors = validate(values);
  success.textContent = "";
  ids.forEach(function (id) {
    const input = document.getElementById(id);
    const slot = form.querySelector('.error[data-for="' + id + '"]');
    slot.textContent = errors[id] || "";
    input.classList.toggle("invalid", Boolean(errors[id]));
  });
  if (Object.keys(errors).length === 0) {
    success.textContent = "Account created!";
    form.reset();
  }
});
